def compute(vars):
    loans = vars["v1"]
    total_assets_pledged = vars["v2"]

    if total_assets_pledged == 0:
        value = None
    else:
        value = (loans / total_assets_pledged) * 100

    return {
        "value": value,
        "trace": {
            "loans": loans,
            "total_assets_pledged": total_assets_pledged,
            "ratio": None if total_assets_pledged == 0 else loans / total_assets_pledged,
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "percentage"
            }
        }
    }
